INSERT INTO `demo_sort2` VALUES ('001', '遵纪守法，遵守职业道德，不以权职谋私，严禁损公肥私、贪污受贿等损害企业利益的行为。', '001', 3);
INSERT INTO `demo_sort2` VALUES ('002', '.自觉维护企业名誉和利益，保守企业秘密，遵守川藏铁路宣传保密纪律，不得擅自外借、复印、外传敏感资料。', '001', 2);
INSERT INTO `demo_sort2` VALUES ('003', '遵守集团公司、项目经理部的各项规章制度。', '001', 3);
INSERT INTO `demo_sort2` VALUES ('004', '按时上班，不得迟到早退、严禁脱岗;严格执行请销假制度，履行请销假手续。', '001', 2);
INSERT INTO `demo_sort2` VALUES ('005', '.忠诚担当，有较强的责任心、大局观，服务意识强,工作不推诿、不怠慢。', '002', 5);
INSERT INTO `demo_sort2` VALUES ('006', '注重团队协作，积极沟通交流，合作共事，相互支持，保持良好的团队氛围。', '002', 5);
