INSERT INTO `nd5701xiangmujinglibuyuang` VALUES (0, '001', '1.遵纪守法，遵守职业道德，不以权职谋私，严禁损公肥私、贪污受贿等损害企业利益的行为。', 0, 100, '2025-01-13 09:59', '613', 0, 'admin', 2.50, 0.00, 0.00, 0.00, 0.00);
INSERT INTO `nd5701xiangmujinglibuyuang` VALUES (0, '002', '2.自觉维护企业名誉和利益，保守企业秘密，遵守川藏铁路宣传保密纪律，不得擅自外借、复印、外传敏感资料。', 0, 101, '2025-01-13 09:59', '613', 0, 'admin', 2.50, 0.00, 0.00, 0.00, 0.00);
INSERT INTO `nd5701xiangmujinglibuyuang` VALUES (0, '003', '3.遵守集团公司、项目经理部的各项规章制度。', 0, 102, '2025-01-13 09:59', '613', 0, 'admin', 2.50, 0.00, 0.00, 0.00, 0.00);
INSERT INTO `nd5701xiangmujinglibuyuang` VALUES (0, '004', '4.按时上班，不得迟到早退、严禁脱岗;严格执行请销假制度，履行请销假手续。', 0, 103, '2025-01-13 09:59', '613', 0, 'admin', 2.50, 0.00, 0.00, 0.00, 0.00);
