INSERT INTO `sys_mapdata` VALUES ('ND1401', '秘书收文', '', '', 'ND14Rpt', 0, '', '', 900, 0, '', '', 8, 0, 0, 0, 0, 'local', '', '', '', '', '', 100, '', '', '', '', '@Ver=1', '', 0, 0, '', '', '', '', '', 2, 0, 500, 760, 0, '', '', '', '', '', 1, '', '', '', '关联单据', 0, '', '', '', NULL, '', 0, '', 0, '', '', '', '', '', 0, 0, 0.00, 0, '', '', NULL, '', '', 0, NULL, 0, NULL, '<center><br/>\n &nbsp; &nbsp;<table style=\"border:none;border-collapse: collapse; width: 700px; \" width=\"780\"><tbody><tr class=\"firstRow\"><td colspan=\"3\" style=\"word-break: break-all;border-left:none;border-right:none;border-top:none;border-color: rgb(255, 0, 0);\" valign=\"top\"><span style=\"color: rgb(255, 0, 0);\"><span style=\"color: rgb(255, 0, 0); font-size: 36px;\"><strong><span style=\"font-size: 36px; font-family: 宋体, SimSun; color: rgb(255, 0, 0);\">国家流程局</span></strong></span><span style=\"color: rgb(255, 0, 0); font-size: 36px; float: right;\"><strong><span style=\"font-size: 36px; font-family: 宋体, SimSun; color: rgb(255, 0, 0);\">（司）收文处理单</span></strong></span><span id=\"common_2\" style=\"padding-left: 205px; color: rgb(255, 0, 0); font-size: 36px;\"><strong><span style=\"font-size: 36px; font-family: 宋体, SimSun; color: rgb(255, 0, 0);\"></span></strong></span></span>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td></tr><tr><td style=\"word-break: break-all;border-left:none;border-color: rgb(255, 0, 0);\" width=\"50%\" valign=\"top\" height=\"77\"><p><span style=\"color: rgb(255, 0, 0);\"><br/></span>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><span style=\"color: rgb(255, 0, 0);\">收文号：&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 〔</span><input type=\"text\" value=\"\" id=\"TB_documentNumber\" name=\"TB_documentNumber\" data-key=\"documentNumber\" data-name=\"公文编号\" data-type=\"Text\" class=\"form-control\" leipiplugins=\"text\" style=\"width:120px\"/><p>公文编号</p><span style=\"color: rgb(255, 0, 0);\">&nbsp; &nbsp; &nbsp; &nbsp; 