INSERT INTO `sys_mapext` VALUES ('ND5701XiangMuJingLiBuYuanG_KaoPingWeiDu_ActiveDDL', 'ND5701XiangMuJingLiBuYuanG', 'ActiveDDL', 'ActiveDDL', '1', 'KaoPingWeiDu', 'SF_KaoPingNeiRong', 'SELECT BH AS No, Name from Sys_SFTableDtl A,Sys_Enum B  Where A.FK_SFTable=~SF_KaoPingNeiRong~ AND B.EnumKey=~KaoPingWeiDu~\nAND CASE IntKey WHEN 0 THEN BH IN(~001~,~002~,~003~,~004~) WHEN 1 THEN BH IN(~005~,~006~)  WHEN 2 THEN BH IN(~007~,~008~,~009~,~010~) ELSE BH=~011~ END AND B.IntKey=@Key', '', '', '', '', '', '', '', 500, 400, 0, 'local', 0, '@IsSelectVal=0', '', '', 0, 1, '', '查找', '', '', '', 1, '', '', 1, '', 0, 1, 1, NULL, '考评内容', 0);
INSERT INTO `sys_mapext` VALUES ('ND5701XiangMuJingLiBuYuanG_PageLoadFullDtl', 'ND5701XiangMuJingLiBuYuanG', 'PageLoadFullDtl', 'PageLoadFullDtl', 'Self', '', '', 'SELECT\n	B.IntKey AS KaoPingWeiDu,\n	BH AS  SF_KaoPingNeiRong,\n	NAME AS SF_KaoPingNeiRongT,\nCASE\n		BH \n		WHEN ~001~ THEN\n		2.5 \n		WHEN ~002~ THEN\n		2.5 \n		WHEN ~003~ THEN\n		2.5 \n		WHEN ~004~ THEN\n		2.5\n		WHEN ~005~ THEN\n		5 	\n		WHEN ~006~ THEN\n		5 \n		WHEN ~007~ THEN\n		2.5 \n		WHEN ~008~ THEN\n		2.5 \n		WHEN ~009~ THEN\n		2.5 \n		WHEN ~010~ THEN\n		5 \n		ELSE 70\n	END AS FenZhi\nFROM\n	Sys_SFTableDtl A,\n	Sys_Enum B \nWHERE\n	A.FK_SFTable = ~SF_KaoPingNeiRong~ \n	AND B.EnumKey = ~KaoPingWeiDu~ \nAND\nCASE\n		IntKey \n		WHEN 0 THEN\n		BH IN ( ~001~, ~002~, ~003~, ~004~ ) \n		WHEN 1 THEN\n		BH IN ( ~005~, ~006~ ) \n		WHEN 2 THEN\n	BH IN ( ~007~, ~008~, ~009~, ~010~ ) ELSE BH = ~011~ \nEND', '', '', '', '', '', 'Self', '', 500, 400, 0, 'local', 0, '', '', '', 0, 1, '', '查找', '', '', '', 1, '', '', 1, '', 0, 1, 1, NULL, '', 0);
