  `path` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'path',
  `Alias` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '别名',
  `IframeOpenType` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'inner' COMMENT 'iframe打开方式',
  `IframeOpenTypeT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'inner' COMMENT 'iframe打开方式',
  `MobileUrlExt` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '移动端连接',
