  `MoreUrl` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '更多链接',
  `MoreLinkModel` int(11) NULL DEFAULT 0 COMMENT '打开方式',
  `PopW` int(11) NULL DEFAULT 500 COMMENT 'Pop宽度',
  `PopH` int(11) NULL DEFAULT 400 COMMENT 'Pop高度',
