  `Idx` int(11) NULL DEFAULT 0 COMMENT '默认的排序',
  `IsDel` int(11) NULL DEFAULT 1 COMMENT '用户是否可删除',
  `IsEnable` int(11) NULL DEFAULT 0 COMMENT '是否禁用?',
  `OrgNo` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'OrgNo',
  `LabOfFZ` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分子标签',
  `SQLOfFZ` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '分子表达式',
  `LabOfFM` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分母标签',
  `SQLOfFM` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '分子表达式',
  `LabOfRate` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '率标签',
  `IsPie` int(11) NULL DEFAULT 0 COMMENT '饼图?',
  `IsLine` int(11) NULL DEFAULT 0 COMMENT '折线图?',
  `IsZZT` int(11) NULL DEFAULT 0 COMMENT '柱状图?',
  `IsRing` int(11) NULL DEFAULT 0 COMMENT '显示环形图?',
  `IsRate` int(11) NULL DEFAULT 0 COMMENT '百分比扇形图?',
  `DefaultChart` int(11) NULL DEFAULT 0 COMMENT '默认显示图形',
  `DBType` int(11) NULL DEFAULT 0 COMMENT '数据源类型',
  `C1Ens` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '列1外键数据(可选)',
  `C2Ens` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '列2外键数据(可选)',
  `C3Ens` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '列3外键数据(可选)',
  `DBSrc` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `H` float(11, 2) NULL DEFAULT 100.00 COMMENT '占的列数',
  `W` float(11, 2) NULL DEFAULT 200.00 COMMENT '占的列数',
  `X` float(11, 2) NULL DEFAULT 200.00 COMMENT '占的列数',
  `Y` float(11, 2) NULL DEFAULT 200.00 COMMENT '占的列数',
  `C0Ens` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '维度0数据',
  `Tag1` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'Tag1',
  `RowSpan` int(11) NULL DEFAULT 1 COMMENT '占的行数',
  `WindowHeight` float(11, 2) NULL DEFAULT 360.00 COMMENT '窗口高度',
  PRIMARY KEY (`No`) USING BTREE,
  INDEX `GPM_WindowTemplate_No`(`No`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'Html信息块' ROW_FORMAT = DYNAMIC;

