-- ----------------------------
-- Table structure for port_org
-- ----------------------------
DROP TABLE IF EXISTS `port_org`;
CREATE TABLE `port_org`  (
  `No` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `Name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `ParentNo` varchar(60) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '父级组织编号',
  `ParentName` varchar(60) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '父级组织名称',
  `Adminer` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `AdminerName` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `SSOUrl` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'SSOUrl',
  `OrgSta` int(11) NULL DEFAULT 0 COMMENT '组织状态',
  `FlowNums` int(11) NULL DEFAULT 0 COMMENT '流程数',
  `FrmNums` int(11) NULL DEFAULT 0 COMMENT '表单数',
  `Users` int(11) NULL DEFAULT 0 COMMENT '用户数',
  `Depts` int(11) NULL DEFAULT 0 COMMENT '部门数',
  `GWFS` int(11) NULL DEFAULT 0 COMMENT '运行中流程',
  `GWFSOver` int(11) NULL DEFAULT 0 COMMENT '结束的流程',
  `Idx` int(11) NULL DEFAULT 0 COMMENT '排序',
  `PrivateKey` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'PrivateKey',
  `JieMi` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'None' COMMENT '解密方式',
  `JieMiT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'None' COMMENT '解密方式',
  `KeyOfJieMi` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '盐值',
  `CorpID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'CorpID',
  `NameFull` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '全称',
  `Addr` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '地址',
  `GUID` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'GUID',
  `DTReg` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DTEnd` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `RegIP` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '注册的IP',
  `RDT` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `RegFrom` int(11) NULL DEFAULT 0 COMMENT '注册来源',
  `WXUseSta` int(11) NULL DEFAULT 0 COMMENT '状态@0=未安装1=使用中@2=卸载.',
  `UrlFrom` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '网站来源',
  `DB` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'DB',
  `AgentName` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '授权方企业名称，即企业简称',
  `AgentId` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '授权方应用id',
  `PermanentCode` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '企业微信永久授权码',
  `AccessToken` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '授权方（企业）access_token',
  `AccessTokenExpiresIn` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `CorpUserMax` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '授权方企业用户规模',
  `CorpAgentMax` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '授权方企业应用数上限',
  `CorpFullName` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '授权方企业的主体名称',
  `SubjectType` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '企业类型，1. 企业; 2. 政府以及事业单位; 3. 其他组织, 4.团队号',
  `VerifiedEndTime` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '认证到期时间',
  `CorpScale` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '企业规模。当企业未设置该属性时，值为空',
  `CorpIndustry` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '企业所属行业。当企业未设置该属性时，值为空',
  `CorpSubIndustry` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '企业所属子行业。当企业未设置该属性时，值为空',
  `Location` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '企业所在地信息, 为空时表示未知',
  PRIMARY KEY (`No`) USING BTREE,
  INDEX `Port_Org_No`(`No`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统信息' ROW_FORMAT = DYNAMIC;

