DROP TABLE IF EXISTS `sys_encfg`;
CREATE TABLE `sys_encfg`  (
  `No` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '实体名称',
  `UIRowStyleGlo` int(11) NULL DEFAULT 0 COMMENT '表格数据行风格(应用全局)',
  `IsEnableDouclickGlo` int(11) NULL DEFAULT 1 COMMENT '是否启动双击打开(应用全局)?',
  `IsEnableFocusField` int(11) NULL DEFAULT 0 COMMENT '是否启用焦点字段?',
  `FocusField` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '焦点字段',
  `IsEnableRefFunc` int(11) NULL DEFAULT 0 COMMENT '是否启用相关功能列?',
  `IsEnableOpenICON` int(11) NULL DEFAULT 0 COMMENT '是否启用打开图标?',
  `IsJM` int(11) NULL DEFAULT 0 COMMENT '是否是加密存储?',
  `IsSelectMore` int(11) NULL DEFAULT 0 COMMENT '是否下拉查询条件多选?',
