  `BtnJS1` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '集合:Url/Javasccript',
  `BtnLab2` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '集合:自定义按钮标签2',
  `BtnJS2` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '集合:Url/Javasccript',
  `BtnLab3` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '集合:自定义按钮标签3',
  `BtnJS3` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '集合:Url/Javasccript',
  `EnBtnLab1` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实体:自定义按钮标签1',
  `EnBtnJS1` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实体:Url/Javasccript',
  `EnBtnLab2` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实体:自定义按钮标签2',
  `EnBtnJS2` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '实体:Url/Javasccript',
  `SearchUrlOpenType` int(11) NULL DEFAULT 0 COMMENT '双击/单击行打开内容',
  `IsRefreshParentPage` int(11) NULL DEFAULT 1 COMMENT '关闭后是否刷新本页面',
  `UrlExt` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '要打开的Url',
  `DoubleOrClickModel` int(11) NULL DEFAULT 0 COMMENT '双击/单击行弹窗模式',
  `OpenModel` int(11) NULL DEFAULT 0 COMMENT '打开方式',
  `OpenModelFunc` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '弹窗方法',
  `WinCardW` int(11) NULL DEFAULT 0 COMMENT '宽度',
  `WinCardH` int(11) NULL DEFAULT 2 COMMENT '高度',
  `AtPara` varchar(3000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'AtPara',
  `PanelIconSize` int(11) NULL DEFAULT 1 COMMENT '实体ICON的大小',
  `IsEnableEnumColor` int(11) NULL DEFAULT 0 COMMENT '是否启用枚举颜色?',
  `EnumColorField` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '枚举颜色字段',
  `FieldGroupDisplayMode` int(11) NULL DEFAULT 1 COMMENT '字段分组显示模式',
  `ShowColModel` int(11) NULL DEFAULT 0 COMMENT '显示列',
  `ShowCols` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '显示列s',
  `HideAttrModel` int(11) NULL DEFAULT 0 COMMENT '字段隐藏规则',
  `HideAttrs` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `HideMethodModel` int(11) NULL DEFAULT 0 COMMENT '方法隐藏规则',
  `HideMethods` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '方法隐藏s',
  `IsRpt` int(11) NULL DEFAULT 1 COMMENT '是否显示报表按钮(在查询工具栏里)?',
  `IsBigScreen` int(11) NULL DEFAULT 0 COMMENT '是否显示大屏按钮(在查询工具栏里)?',
  `PosRefFuncMobile` int(11) NULL DEFAULT 0 COMMENT '(移动端)相关功能显示位置',
  `IconEnumAttr` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '枚举Icon图标字段',
  `MHideAttrModel` int(11) NULL DEFAULT 0 COMMENT '字段隐藏规则',
  `MHideAttrs` varchar(900) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `MHideMethodModel` int(11) NULL DEFAULT 0 COMMENT '方法隐藏规则',
  `MHideMethods` varchar(900) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `EnableMobileSelect` int(11) NULL DEFAULT 1 COMMENT '是否启用移动端选择?',
  `EnableFavorite` int(11) NULL DEFAULT 0 COMMENT '是否启用收藏?',
  `ShowNumIdx` int(11) NULL DEFAULT 0 COMMENT '是否显示数字索引',
  `Name` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '中文名',
  `TableName` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '表名',
  `OrgNo` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '隶属组织',
  `FrmID` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '表',
  `Creater` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '中文名',
  `FiCreater` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '创建人关键字段',
  `FieldOfCreater` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '创建人关键字段',
  `FieldOfDeptNo` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '中文名',
  `FieldOfRec` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '创建人字段',
  `FieldOfOrgNo` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '组织字段',
  `EnablePrint` int(11) NULL DEFAULT 0 COMMENT '启用打印?（前端实现）',
  PRIMARY KEY (`No`) USING BTREE,
  INDEX `Sys_EnCfg_No`(`No`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '实体配置' ROW_FORMAT = DYNAMIC;

