-- ----------------------------
-- Table structure for sys_frmattachment
-- ----------------------------
DROP TABLE IF EXISTS `sys_frmattachment`;
CREATE TABLE `sys_frmattachment`  (
  `MyPK` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '主键MyPK',
  `FK_MapData` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '表单ID',
  `NoOfObj` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '附件编号',
  `FK_Node` int(11) NULL DEFAULT 0 COMMENT '节点控制(对sln有效)',
  `AthRunModel` int(11) NULL DEFAULT 0 COMMENT '运行模式',
  `AthSaveWay` int(11) NULL DEFAULT 0 COMMENT '保存方式',
  `Name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '名称',
  `Exts` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '要求上传的格式',
  `NumOfUpload` int(11) NULL DEFAULT 0 COMMENT '最小上传数量',
  `TopNumOfUpload` int(11) NULL DEFAULT 99 COMMENT '最大上传数量',
  `FileMaxSize` int(11) NULL DEFAULT 10240 COMMENT '附件最大限制(KB)',
  `UploadFileNumCheck` int(11) NULL DEFAULT 0 COMMENT '上传校验方式',
  `Sort` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '类别(可为空)',
  `H` float(11, 2) NULL DEFAULT 150.00 COMMENT 'H',
  `IsUpload` int(11) NULL DEFAULT 1 COMMENT '是否可以上传',
  `IsVisable` int(11) NULL DEFAULT 1 COMMENT '是否可见',
  `FileType` int(11) NULL DEFAULT 0 COMMENT '附件类型',
  `ReadRole` int(11) NULL DEFAULT 0 COMMENT '阅读规则',
  `PicUploadType` int(11) NULL DEFAULT 0 COMMENT '图片附件上传方式',
  `DeleteWay` int(11) NULL DEFAULT 1 COMMENT '附件删除规则(0=不能删除1=删除所有2=只能删除自己上传的',
  `IsDownload` int(11) NULL DEFAULT 1 COMMENT '是否可以下载',
  `IsAutoSize` int(11) NULL DEFAULT 1 COMMENT '自动控制大小',
  `IsNote` int(11) NULL DEFAULT 1 COMMENT '是否增加备注',
  `IsExpCol` int(11) NULL DEFAULT 0 COMMENT '是否启用扩展列',
  `IsShowTitle` int(11) NULL DEFAULT 1 COMMENT '是否显示标题列',
  `UploadType` int(11) NULL DEFAULT 0 COMMENT '上传类型0单个1多个2指定',
  `IsIdx` int(11) NULL DEFAULT 0 COMMENT '是否排序',
  `CtrlWay` int(11) NULL DEFAULT 4 COMMENT '控制呈现控制方式0=PK,1=FID,2=ParentID',
  `AthUploadWay` int(11) NULL DEFAULT 0 COMMENT '控制上传控制方式0=继承模式,1=协作模式.',
  `DataRefNoOfObj` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据引用组件ID',
  `AtPara` varchar(3000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'AtPara',
  `GroupID` int(11) NULL DEFAULT 0 COMMENT 'GroupID',
  `GUID` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'GUID',
  `IsEnableTemplate` int(11) NULL DEFAULT 0 COMMENT '是否启用模板下载?',
  `AthSingleRole` int(11) NULL DEFAULT 0 COMMENT '模板规则',
  `AthEditModel` int(11) NULL DEFAULT 0 COMMENT '在线编辑模式',
  `IsToHeLiuHZ` int(11) NULL DEFAULT 1 COMMENT '该字段单附件是否要汇总到合流节点上去？(对子线程节点有效)',
  `IsHeLiuHuiZong` int(11) NULL DEFAULT 1 COMMENT '是否是合流节点的汇总字段单附件组件？(对合流节点有效)',
  `IsTurn2Html` int(11) NULL DEFAULT 0 COMMENT '是否转换成html(方便手机浏览)',
  `MyFileNum` int(11) NULL DEFAULT 0 COMMENT '附件模板',
  `Nameen` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '英文',
  `Nameja` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '日文',
  `AthEditType` int(11) NULL DEFAULT 0 COMMENT '在线编辑方式',
  `OpenDesc` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '上传说明',
  PRIMARY KEY (`MyPK`) USING BTREE,
  INDEX `Sys_FrmAttachment_MyPK`(`MyPK`) USING BTREE,
  INDEX `Sys_Frmattachment_FK_MapData`(`FK_MapData`) USING BTREE,
  INDEX `Sys_Frmattachment_FK_Node`(`FK_Node`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '附件' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_frmattachment
-- ----------------------------

