DROP TABLE IF EXISTS `sys_mapext`;
CREATE TABLE `sys_mapext`  (
  `MyPK` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '主键MyPK',
  `FK_MapData` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '表单ID',
  `ExtModel` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `ExtType` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DoWay` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '执行方式',
  `AttrOfOper` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `AttrsOfActive` varchar(900) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '激活的字段',
  `Doc` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容',
  `Tag` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Tag',
  `Tag1` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `Tag2` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `Tag3` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `Tag4` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `Tag5` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Tag5',
  `Tag6` varchar(2000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Tag5',
  `H` int(11) NULL DEFAULT 500 COMMENT '高度',
  `W` int(11) NULL DEFAULT 400 COMMENT '宽度',
  `DBType` int(11) NULL DEFAULT 0 COMMENT '数据类型',
  `FK_DBSrc` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据源',
  `PRI` int(11) NULL DEFAULT 0 COMMENT 'PRI/顺序号',
  `AtPara` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '参数',
  `RefPKVal` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'RefPKVal',
  `SearchTip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '搜索提示',
  `ShowModel` int(11) NULL DEFAULT 0 COMMENT '展示方式',
  `PopSelectType` int(11) NULL DEFAULT 1 COMMENT '选择类型',
  `Title` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '标题',
  `BtnLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '查找' COMMENT '查找按钮标签',
  `TagT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '联动的控件',
  `Tag1T` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DocT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '日期从',
  `IsFirstLoad` int(11) NULL DEFAULT 1 COMMENT '打开是否直接加载数据',
  `Tag2T` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'Tag2',
  `Tag3T` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'Tag3',
  `OpenPopType` int(11) NULL DEFAULT 1 COMMENT '打开Pop弹出窗的方式',
  `Tag6T` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'Tag6',
  `IsLazy` int(11) NULL DEFAULT 0 COMMENT '是否懒加载?',
  `NodeCascade` int(11) NULL DEFAULT 1 COMMENT '父子节点是否级联',
  `IsLoadFull` int(11) NULL DEFAULT 1 COMMENT '加载页面时是否自动填充',
  `HtmlText` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '内容',
  `AttrsOfActiveT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '联动的下拉框',
  `IsSelectVal` int(11) NULL DEFAULT 0 COMMENT '级联是否默认选择值',
  PRIMARY KEY (`MyPK`) USING BTREE,
  INDEX `Sys_MapExt_MyPK`(`MyPK`) USING BTREE,
  INDEX `Sys_MapExt_FK_MapData`(`FK_MapData`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '业务逻辑' ROW_FORMAT = DYNAMIC;

