  `DeptNo` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '隶属部门',
  `DeptNoT` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '部门名称',
  `FK_Flow` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '流程',
  PRIMARY KEY (`MyPK`) USING BTREE,
  INDEX `WF_CH_MyPK`(`MyPK`) USING BTREE,
  INDEX `WF_CH_WorkID`(`WorkID`) USING BTREE,
  INDEX `WF_CH_WorkID_EmpNo`(`WorkID`, `EmpNo`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '时效考核' ROW_FORMAT = DYNAMIC;

