DROP TABLE IF EXISTS `wf_direction`;
CREATE TABLE `wf_direction`  (
  `MyPK` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '主键MyPK',
  `FK_Flow` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `Node` int(11) NULL DEFAULT 0 COMMENT '从节点',
  `ToNode` int(11) NULL DEFAULT 0 COMMENT '到节点',
  `ToNodeName` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '到达节点名称',
  `GateWay` int(11) NULL DEFAULT 0 COMMENT '网关显示?',
  `NodeType` int(11) NULL DEFAULT 0 COMMENT 'ToNode类型0=工作,1=路由,2=抄送,3=子流程,4=结束',
  `Vertices` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `Des` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述',
  `Idx` int(11) NULL DEFAULT 0 COMMENT '计算优先级顺序',
  `FromPort` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '出发点连接桩位置',
  `ToPort` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '到达点连接桩位置',
  PRIMARY KEY (`MyPK`) USING BTREE,
  INDEX `WF_Direction_MyPK`(`MyPK`) USING BTREE,
  INDEX `WF_Direction_Node`(`Node`) USING BTREE,
  INDEX `WF_Direction_Node_ToNode`(`Node`, `ToNode`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '节点方向信息' ROW_FORMAT = DYNAMIC;

