-- ----------------------------
-- Table structure for wf_emp
-- ----------------------------
DROP TABLE IF EXISTS `wf_emp`;
CREATE TABLE `wf_emp`  (
  `No` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'No',
  `Name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Name',
  `UseSta` int(11) NULL DEFAULT 1 COMMENT '用户状态0禁用,1正常.',
  `Tel` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Tel',
  `FK_Dept` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'FK_Dept',
  `Stas` varchar(3000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '角色s',
  `Depts` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '部门s',
  `Msg` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '消息',
  `OrgNo` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'OrgNo',
  `SPass` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '图片签名密码',
  `Author` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权人',
  `AuthorDate` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权日期',
  `Token` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'Token',
  `AtPara` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'AtPara',
  `StartFlows` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '可以发起的流程',
  `Email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '邮件',
  `FrmStyle` int(11) NULL DEFAULT 0 COMMENT '表单风格',
  `SysLang` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'CH' COMMENT '系统语言',
  `SysLangT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'CH' COMMENT '系统语言',
  `UserID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'UserID',
  `EM_SeverType` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'IMAP' COMMENT '服务器类型',
  `EM_SeverTypeT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'IMAP' COMMENT '服务器类型',
  `EM_Email` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '邮件账号',
  `EM_Pass` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '密码',
  `EM_IMAP_SeverIP` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'IMAP服务器',
  `EM_IMAP_Port` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '端口',
  `EM_IMAP_SSL` int(11) NULL DEFAULT 0 COMMENT 'SSL',
  `EM_SMTP_SeverIP` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'SMTP服务器',
  `EM_SMTP_Port` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '端口',
  `EM_SMTP_SSL` int(11) NULL DEFAULT 0 COMMENT 'SSL',
  `EM_SMTP_SenderName` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '发件人名称',
  `EM_SMTP_SenderSigner` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '签名',
  PRIMARY KEY (`No`) USING BTREE,
  INDEX `WF_Emp_No`(`No`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '操作员' ROW_FORMAT = DYNAMIC;

