-- Records of wf_emp
-- ----------------------------

-- ----------------------------
-- Table structure for wf_flow
-- ----------------------------
DROP TABLE IF EXISTS `wf_flow`;
CREATE TABLE `wf_flow`  (
  `No` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `FK_FlowSort` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `FK_FlowSortText` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '类别',
  `Name` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `FlowMark` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流程标记',
  `FlowEventEntity` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流程事件实体',
  `TitleRole` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '标题生成规则',
  `TitleRoleNodes` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '生成标题的节点',
  `IsCanStart` int(11) NULL DEFAULT 1 COMMENT '可以独立启动否？(独立启动的流程可以显示在发起流程列表里)',
  `IsFullSA` int(11) NULL DEFAULT 0 COMMENT '是否自动计算未来的处理人？',
  `GuestFlowRole` int(11) NULL DEFAULT 0 COMMENT '外部用户参与流程规则',
  `Draft` int(11) NULL DEFAULT 0 COMMENT '草稿规则',
  `SysType` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '系统类型',
  `Tester` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '发起测试人',
  `ChartType` int(11) NULL DEFAULT 1 COMMENT '节点图形类型',
  `Idx` int(11) NULL DEFAULT 0 COMMENT '显示顺序号(在发起列表中)',
  `CreateDate` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建日期',
  `Creater` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `IsBatchStart` int(11) NULL DEFAULT 0 COMMENT '是否可以批量发起流程？(如果是就要设置发起的需要填写的字段,多个用逗号分开)',
  `BatchStartFields` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `IsResetData` int(11) NULL DEFAULT 0 COMMENT '是否启用开始节点数据重置按钮？已经取消)',
  `IsLoadPriData` int(11) NULL DEFAULT 0 COMMENT '是否自动装载上一笔数据？',
  `IsDBTemplate` int(11) NULL DEFAULT 1 COMMENT '是否启用数据模版？',
  `IsStartInMobile` int(11) NULL DEFAULT 1 COMMENT '是否可以在手机里启用？(如果发起表单特别复杂就不要在手机里启用了)',
  `IsMD5` int(11) NULL DEFAULT 0 COMMENT '是否是数据防止篡改(MD5数据加密防篡改)',
  `IsJM` int(11) NULL DEFAULT 0 COMMENT '是否是数据加密流程(把所有字段加密存储)',
  `IsEnableDBVer` int(11) NULL DEFAULT 0 COMMENT '是否是启用数据版本控制',
  `PTable` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流程数据存储表',
  `BillNoFormat` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '单据编号格式',
  `BuessFields` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '关键业务字段',
  `AdvEmps` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '高级查询人员',
  `IsTruckEnable` int(11) NULL DEFAULT 1 COMMENT '是否显示轨迹图',
  `IsTimeBaseEnable` int(11) NULL DEFAULT 1 COMMENT '是否显示时间轴',
  `IsTableEnable` int(11) NULL DEFAULT 1 COMMENT '是否显示时间表',
  `SubFlowShowType` int(11) NULL DEFAULT 0 COMMENT '子流程轨迹图显示模式',
  `TrackOrderBy` int(11) NULL DEFAULT 0 COMMENT '排序方式',
  `FlowRunWay` int(11) NULL DEFAULT 0 COMMENT '运行方式',
  `WorkModel` int(11) NULL DEFAULT 0 COMMENT 'WorkModel',
  `RunObj` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '运行内容',
  `Note` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '备注',
  `RunSQL` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '流程结束执行后执行的SQL',
  `NumOfBill` int(11) NULL DEFAULT 0 COMMENT '是否有单据',
  `NumOfDtl` int(11) NULL DEFAULT 0 COMMENT 'NumOfDtl',
  `FlowAppType` int(11) NULL DEFAULT 0 COMMENT '流程类型',
  `SDTOfFlowRole` int(11) NULL DEFAULT 0 COMMENT '流程计划完成日期计算规则',
  `SDTOfFlowRoleSQL` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '流程计划完成日期计算规则SQL',
  `FrmUrl` varchar(150) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '表单Url',
  `DRCtrlType` int(11) NULL DEFAULT 0 COMMENT '部门查询权限控制方式',
  `IsToParentNextNode` int(11) NULL DEFAULT 0 COMMENT '子流程运行到该节点时，让父流程自动运行到下一步',
  `StartLimitRole` int(11) NULL DEFAULT 0 COMMENT '启动限制规则',
  `StartLimitPara` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '规则内容',
  `StartLimitAlert` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '限制提示',
  `StartLimitWhen` int(11) NULL DEFAULT 0 COMMENT '提示时间',
  `StartGuideWay` int(11) NULL DEFAULT 0 COMMENT '前置导航方式',
  `StartGuideLink` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '右侧的连接',
  `StartGuideLab` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '连接标签',
  `StartGuidePara1` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '参数1',
  `StartGuidePara2` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '参数2',
  `StartGuidePara3` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '参数3',
  `Ver` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '版本号',
  `OrgNo` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'OrgNo',
  `DevModelType` int(11) NULL DEFAULT 0 COMMENT '设计模式',
  `DevModelPara` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '设计模式参数',
  `AtPara` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `DataDTSWay` int(11) NULL DEFAULT 0 COMMENT '同步方式',
  `DTSDBSrc` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '数据源',
  `DTSBTable` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '业务表名',
  `DTSBTablePK` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '业务表主键',
  `DTSSpecNodes` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '同步字段',
  `DTSTime` int(11) NULL DEFAULT 0 COMMENT '执行同步时间点',
  `DTSFields` varchar(900) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '要同步的字段s,中间用逗号分开.',
  `FlowDevModel` int(11) NULL DEFAULT 0 COMMENT '设计模式',
  `Icon` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `TestSysPara` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `TestFrmPara` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `MyFileName` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'sss',
  `MyFilePath` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'MyFilePath',
  `MyFileExt` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'MyFileExt',
  `WebPath` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'WebPath',
  `MyFileH` int(11) NULL DEFAULT 0 COMMENT 'MyFileH',
  `MyFileW` int(11) NULL DEFAULT 0 COMMENT 'MyFileW',
  `MyFileSize` float(11, 2) NULL DEFAULT 0.00 COMMENT 'MyFileSize',
  `PStarter` int(11) NULL DEFAULT 1 COMMENT '发起人可看(必选)',
  `PWorker` int(11) NULL DEFAULT 1 COMMENT '参与人可看(必选)',
  `PCCer` int(11) NULL DEFAULT 1 COMMENT '被抄送人可看(必选)',
  `PAnyOne` int(11) NULL DEFAULT 0 COMMENT '任何人可见',
  `PMyDept` int(11) NULL DEFAULT 1 COMMENT '本部门人可看',
  `PPMyDept` int(11) NULL DEFAULT 1 COMMENT '直属上级部门可看',
  `PPDept` int(11) NULL DEFAULT 1 COMMENT '上级部门可看',
  `PSameDept` int(11) NULL DEFAULT 1 COMMENT '平级部门可看',
  `PSpecDept` int(11) NULL DEFAULT 1 COMMENT '指定部门可看',
  `PSpecDeptExt` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '部门编号',
  `PSpecSta` int(11) NULL DEFAULT 1 COMMENT '指定的角色可看',
  `PSpecStaExt` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '角色编号',
  `PSpecGroup` int(11) NULL DEFAULT 1 COMMENT '指定的权限组可看',
  `PSpecGroupExt` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '权限组',
  `PSpecEmp` int(11) NULL DEFAULT 1 COMMENT '指定的人员可看',
  `PSpecEmpExt` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '指定的人员编号',
  `MyDeptRole` int(11) NULL DEFAULT 0 COMMENT '本部门发起的流程',
  `ShareSln` int(11) NULL DEFAULT NULL COMMENT '流程共享方案',
  `FK_FlowSortT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '类别',
  `DTSWay` int(11) NULL DEFAULT 0 COMMENT 'DTSWay',
  `BatchListCount` int(11) NULL DEFAULT 0 COMMENT 'BatchListCount',
  `DeadLineRole` int(11) NULL DEFAULT 0 COMMENT 'DeadLineRole',
  `DesignTime` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `BuessPKFields` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '业务主键字段s',
  `IsFrmEnable` int(11) NULL DEFAULT 0 COMMENT '是否显示表单',
  `IsOPEnable` int(11) NULL DEFAULT 0 COMMENT '是否显示操作',
  `Orgs` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '共享组织',
  `OrgsT` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '组织名称',
  `BuessFieldRole` int(11) NULL DEFAULT 0 COMMENT '业务字段规则',
  `BuessFieldNames` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '名称',
  `Days` int(11) NULL DEFAULT 0 COMMENT '天数',
  `Hours` int(11) NULL DEFAULT 0 COMMENT '小时数',
  `MM` int(11) NULL DEFAULT 0 COMMENT '分钟数',
  `FK_DBSrc` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '数据源',
  `CCORShareLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '抄送/分享' COMMENT '抄送/分享',
  `CCORShareEnable` int(11) NULL DEFAULT 0 COMMENT '是否在查看流程中启用',
  `IsWaterMark` int(11) NULL DEFAULT 0 COMMENT '表单是否启用水印',
  `WaterMarkText` int(11) NULL DEFAULT 0 COMMENT '水印默认展示',
  `BatStartRole` int(11) NULL DEFAULT 0 COMMENT 'BatStartRole',
  PRIMARY KEY (`No`) USING BTREE,
  INDEX `WF_Flow_No`(`No`) USING BTREE,
  INDEX `WF_Flow_FK_FlowSort`(`FK_FlowSort`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '流程模版' ROW_FORMAT = DYNAMIC;

