  `SendJS` varchar(999) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '按钮JS函数',
  `DelayedSendLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '延期发送按钮标签',
  `DelayedSendEnable` int(11) NULL DEFAULT 0 COMMENT '是否启用',
