  `SelectorP2` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `SelectorP3` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `SelectorP4` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `CancelNodes` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '可撤销的节点',
  `SubThreadType` int(11) NULL DEFAULT 0 COMMENT 'SubThreadType',
  `IsShowReturnNodeInToolbar` int(11) NULL DEFAULT 0 COMMENT '退回节点是否现在工具栏',
