  `ReturnNodes` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '可退回到的节点',
  `ReturnNodesT` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'ReturnNodes',
  `CancelNodesT` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'CancelNodes',
  `JumpToNodesT` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'JumpToNodes',
  `FWCTimeModel` int(11) NULL DEFAULT 0 COMMENT '时序模式',
  `TimeShowRole` int(11) NULL DEFAULT 1 COMMENT '审批时间显示规则',
  `CheckFieldT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '签批字段',
  `NodeFrmIDT` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '节点表单名',
  `FrmSummaryFieldRole` int(11) NULL DEFAULT 0 COMMENT '摘要字段规则',
  `FrmSummaryFields` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '摘要字段s',
  `FrmSummaryNames` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '字段名称',
  `SheetTreeModel` int(11) NULL DEFAULT 0 COMMENT '展示方式设置',
  `IsChangeFWCTime` int(11) NULL DEFAULT 0 COMMENT '是否可以重新编辑审核时间？',
  `PreplaceWokerLab` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '预置处理人' COMMENT '预置处理人',
  `PreplaceWokerRole` int(11) NULL DEFAULT 0 COMMENT '规则',
  `DeliveryParasT` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT 'DeliveryParas',
  `GovDocSta` int(11) NULL DEFAULT 0 COMMENT '组件状态',
  `OfficeTrackLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '公文版本' COMMENT '公文版本',
  `OfficeTrackEnalbe` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `SelfFormEnRoot` int(11) NULL DEFAULT 0 COMMENT 'SelfFormEnRoot',
  `CtrlIDVisable` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '隐藏的ID',
  `CtrlIDReadonly` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '只读的ID',
  `FrmSln` int(11) NULL DEFAULT 0 COMMENT '表单方案',
  `FlowNo` int(11) NULL DEFAULT 0 COMMENT '流程编号',
  `DownGovLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '下载公文' COMMENT '下载公文',
  `DownGovEnable` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `KKViewLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'KK在线预览' COMMENT 'KK在线预览',
  `KKViewEnable` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `DownVSTOLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '下载VSTO插件' COMMENT '下载VSTO插件',
  `DownVSTOEnable` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `AiLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'Ai助理' COMMENT 'Ai助理',
  `AiAssistant` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `XieZuoRate` int(11) NULL DEFAULT 0 COMMENT '协作模式完成规则',
  `CHWayOfTimeRole` int(11) NULL DEFAULT 1 COMMENT '时间计算方式',
  `CHWayOfTimeRoleField` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '选字段(对表单字段有效)',
  `CHWayOfTimeRoleFieldT` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '' COMMENT '选字段(对表单字段有效)',
  `DownGovPDFLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '下载公文正文(pdf)' COMMENT '下载公文正文(pdf)',
  `DownGovPDFEnable` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `TeamReturner` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `FormUrlMobile` varchar(300) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'http://' COMMENT '表单URL(移动端)',
  `FixFlow` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '冻结' COMMENT '冻结按钮标签',
  `FixEnable` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `WaitIframeMsg` int(11) NULL DEFAULT 0 COMMENT '是否等待嵌入式表单消息',
  `IsOpenSelecter` int(11) NULL DEFAULT 0 COMMENT '找不到接收人是否手工选择?',
  `PreplaceWokerEnable` int(11) NULL DEFAULT 0 COMMENT '规则',
  `CutEnderEmp` int(11) NULL DEFAULT 0 COMMENT '去掉最后一个接受人',
  `CanCelLab` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '作废' COMMENT '作废按钮标签',
  `CanCelEnable` int(11) NULL DEFAULT 0 COMMENT '是否启用',
  `IsEnableLoadDefaulEmps` int(11) NULL DEFAULT 0 COMMENT '是否加载默认的人员(对使用通用人员选择器有效)？',
  `AllowMultipleEditors` int(11) NULL DEFAULT 0 COMMENT '是否允许多人编辑',
  PRIMARY KEY (`NodeID`) USING BTREE,
  INDEX `WF_Node_NodeID`(`NodeID`) USING BTREE,
  INDEX `WF_Node_FK_Flow`(`FK_Flow`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '父子流程' ROW_FORMAT = DYNAMIC;

