-- ----------------------------
-- View structure for v_flowstarterbpm
-- ----------------------------
DROP VIEW IF EXISTS `v_flowstarterbpm`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_flowstarterbpm` AS select `a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`c`.`FK_Emp` AS `FK_Emp`,`c`.`OrgNo` AS `OrgNo` from ((`wf_node` `a` join `wf_nodestation` `b`) join `port_deptempstation` `c`) where ((`a`.`NodePosType` = 0) and (`a`.`NodeID` = `b`.`FK_Node`) and (`b`.`FK_Station` = `c`.`FK_Station`) and ((`a`.`DeliveryWay` = 0) or (`a`.`DeliveryWay` = 14))) union select `a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`c`.`FK_Emp` AS `FK_Emp`,`c`.`OrgNo` AS `OrgNo` from ((`wf_node` `a` join `wf_nodedept` `b`) join `port_deptemp` `c`) where ((`a`.`NodePosType` = 0) and (`a`.`NodeID` = `b`.`FK_Node`) and (`b`.`FK_Dept` = `c`.`FK_Dept`) and (`a`.`DeliveryWay` = 1)) union select `a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`b`.`FK_Emp` AS `FK_Emp`,`c`.`OrgNo` AS `OrgNo` from ((`wf_node` `a` join `wf_nodeemp` `b`) join `port_emp` `c`) where ((`a`.`NodePosType` = 0) and (`a`.`NodeID` = `b`.`FK_Node`) and (`a`.`DeliveryWay` = 3) and (`b`.`FK_Emp` = `c`.`No`)) union select `a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`b`.`No` AS `FK_Emp`,`b`.`OrgNo` AS `OrgNo` from ((`wf_node` `a` join `port_emp` `b`) join `wf_flow` `c`) where ((`a`.`NodePosType` = 0) and (`a`.`DeliveryWay` = 4) and (`a`.`FK_Flow` = `c`.`No`) and ((`b`.`OrgNo` = `c`.`OrgNo`) or (isnull(`b`.`OrgNo`) and isnull(`c`.`OrgNo`)))) union select `a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`e`.`FK_Emp` AS `FK_Emp`,`e`.`OrgNo` AS `OrgNo` from (((`wf_node` `a` join `wf_nodedept` `b`) join `wf_nodestation` `c`) join `port_deptempstation` `e`) where ((`a`.`NodePosType` = 0) and (`a`.`NodeID` = `b`.`FK_Node`) and (`a`.`NodeID` = `c`.`FK_Node`) and (`b`.`FK_Dept` = `e`.`FK_Dept`) and (`c`.`FK_Station` = `e`.`FK_Station`) and (`a`.`DeliveryWay` = 9)) union select `a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`c`.`No` AS `FK_Emp`,`b`.`OrgNo` AS `OrgNo` from ((`wf_node` `a` join `wf_floworg` `b`) join `port_emp` `c`) where ((`a`.`FK_Flow` = `b`.`FlowNo`) and ((`b`.`OrgNo` = `c`.`OrgNo`) or (isnull(`b`.`OrgNo`) and isnull(`c`.`OrgNo`))) and ((`a`.`DeliveryWay` = 22) or (`a`.`DeliveryWay` = 51)));

