-- View structure for wf_empworks
-- ----------------------------
DROP VIEW IF EXISTS `wf_empworks`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `wf_empworks` AS select `a`.`PRI` AS `PRI`,`a`.`WorkID` AS `WorkID`,`b`.`IsRead` AS `IsRead`,`a`.`Starter` AS `Starter`,`a`.`StarterName` AS `StarterName`,`a`.`WFState` AS `WFState`,`a`.`FK_Dept` AS `FK_Dept`,`a`.`DeptName` AS `DeptName`,`b`.`FK_Dept` AS `TodoEmpDeptNo`,`a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`a`.`PWorkID` AS `PWorkID`,`a`.`PFlowNo` AS `PFlowNo`,`b`.`FK_Node` AS `FK_Node`,`b`.`NodeName` AS `NodeName`,`a`.`Title` AS `Title`,`a`.`RDT` AS `RDT`,`b`.`RDT` AS `ADT`,`b`.`SDT` AS `SDT`,`b`.`FK_Emp` AS `FK_Emp`,`b`.`FID` AS `FID`,`a`.`FK_FlowSort` AS `FK_FlowSort`,`a`.`SysType` AS `SysType`,`a`.`SDTOfNode` AS `SDTOfNode`,`a`.`SendDT` AS `SendDT`,`a`.`GuestNo` AS `GuestNo`,`a`.`GuestName` AS `GuestName`,`a`.`BillNo` AS `BillNo`,`a`.`TodoEmps` AS `TodoEmps`,`a`.`TodoEmpsNum` AS `TodoEmpsNum`,`a`.`TodoSta` AS `TodoSta`,`a`.`TaskSta` AS `TaskSta`,`a`.`FlowNote` AS `FlowNote`,0 AS `ListType`,`a`.`Sender` AS `Sender`,`a`.`AtPara` AS `AtPara`,`a`.`DomainExt` AS `DomainExt`,`a`.`OrgNo` AS `OrgNo`,`c`.`Idx` AS `FlowIdx`,`d`.`Idx` AS `FlowSortIdx` from (((`wf_generworkflow` `a` join `wf_generworkerlist` `b`) join `wf_flow` `c`) join `wf_flowsort` `d`) where ((`b`.`IsEnable` = 1) and (`b`.`IsPass` = 0) and (`a`.`WorkID` = `b`.`WorkID`) and (`a`.`FK_Node` = `b`.`FK_Node`) and (`a`.`WFState` <> 0) and (`b`.`WhoExeIt` <> 1) and (`a`.`FK_Flow` = `c`.`No`) and (`a`.`FK_FlowSort` = `d`.`No`) and (`c`.`FK_FlowSort` = `d`.`No`)) union select `a`.`PRI` AS `PRI`,`a`.`WorkID` AS `WorkID`,`b`.`Sta` AS `IsRead`,`a`.`Starter` AS `Starter`,`a`.`StarterName` AS `StarterName`,2 AS `WFState`,`a`.`FK_Dept` AS `FK_Dept`,`a`.`DeptName` AS `DeptName`,'' AS `TodoEmpDeptNo`,`a`.`FK_Flow` AS `FK_Flow`,`a`.`FlowName` AS `FlowName`,`a`.`PWorkID` AS `PWorkID`,`a`.`PFlowNo` AS `PFlowNo`,`b`.`NodeIDCC` AS `FK_Node`,`b`.`NodeIDCCName` AS `NodeName`,`a`.`Title` AS `Title`,`a`.`RDT` AS `RDT`,`b`.`RDT` AS `ADT`,`b`.`RDT` AS `SDT`,`b`.`CCTo` AS `FK_Emp`,`b`.`FID` AS `FID`,`a`.`FK_FlowSort` AS `FK_FlowSort`,`a`.`SysType` AS `SysType`,`a`.`SDTOfNode` AS `SDTOfNode`,`a`.`SendDT` AS `SendDT`,`a`.`GuestNo` AS `GuestNo`,`a`.`GuestName` AS `GuestName`,`a`.`BillNo` AS `BillNo`,`a`.`TodoEmps` AS `TodoEmps`,`a`.`TodoEmpsNum` AS `TodoEmpsNum`,0 AS `TodoSta`,0 AS `TaskSta`,`a`.`FlowNote` AS `FlowNote`,1 AS `ListType`,`b`.`RecEmpNo` AS `Sender`,concat('@IsCC=1','@NodeIDWork=',`b`.`NodeIDWork`,`a`.`AtPara`) AS `AtPara`,`a`.`DomainExt` AS `DomainExt`,`a`.`OrgNo` AS `OrgNo`,`c`.`Idx` AS `FlowIdx`,`d`.`Idx` AS `FlowSortIdx` from (((`wf_generworkflow` `a` join `wf_cclist` `b`) join `wf_flow` `c`) join `wf_flowsort` `d`) where ((`a`.`WorkID` = `b`.`WorkID`) and (`b`.`Sta` <= 1) and (`b`.`InEmpWorks` = 1) and (`a`.`WFState` <> 0) and (`a`.`FK_Flow` = `c`.`No`) and (`a`.`FK_FlowSort` = `d`.`No`) and (`c`.`FK_FlowSort` = `d`.`No`));

