-- View structure for wf_todolist
-- ----------------------------
DROP VIEW IF EXISTS `wf_todolist`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `wf_todolist` AS select concat(`a`.`WorkID`,'_',`b`.`FK_Emp`) AS `MyPK`,`a`.`WorkID` AS `WorkID`,`a`.`WorkID` AS `OID`,`a`.`Title` AS `Title`,`a`.`StarterName` AS `StarterName`,`a`.`RDT` AS `RDT`,`a`.`NodeName` AS `NodeName`,`a`.`TodoEmps` AS `TodoEmps`,`a`.`SendDT` AS `SendDT`,`a`.`Sender` AS `Sender`,`a`.`FK_Flow` AS `FlowNo`,`a`.`FlowName` AS `FlowName`,`b`.`FK_Emp` AS `EmpNo`,`a`.`OrgNo` AS `OrgNo` from (`wf_generworkflow` `a` join `wf_generworkerlist` `b`) where ((`a`.`WorkID` = `b`.`WorkID`) and (`a`.`FK_Node` = `b`.`FK_Node`) and (`b`.`IsEnable` = 1) and (`b`.`IsPass` = 0));

-- ----------------------------
-- Procedure structure for ModifyTrackMyPK
-- ----------------------------
DROP PROCEDURE IF EXISTS `ModifyTrackMyPK`;
delimiter ;;
CREATE PROCEDURE `ModifyTrackMyPK`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE alter_sql TEXT;

    DECLARE cursor_sql CURSOR FOR
        SELECT CONCAT('ALTER TABLE ', TABLE_NAME, ' MODIFY MyPK BIGINT;')
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = 'ke'  -- 替换为你的数据库名
        AND TABLE_NAME LIKE 'nd%track'
        AND COLUMN_NAME = 'MyPK';

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cursor_sql;

    read_loop: LOOP
        FETCH cursor_sql INTO alter_sql;
        IF done THEN
            LEAVE read_loop;
        END IF;
        -- 执行 ALTER TABLE 语句
        SET @sql = alter_sql;
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END LOOP;

    CLOSE cursor_sql;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
